		&dev_pre_21,
		&dev_pre_40,
		&dev_pre_50,
		&dev_post_60,
		&dev_post_61,
		&dev_app_80,
		&dev_app_81,
	};

	if (init_sequence_idx != ARRAY_SIZE(expected_sequence)) {
